@startuml

class Home {}

class Department {}

class Room {}

class Bed {}

class Category {
  + price : float
}

enum StayType {
  RH
  RNH
  SF
}

class Inhabitant {
  + name : string
  + identificationData : string
}

class Registration {
  + registrationDate : date
}

class Assessment {
  + needsHelpEating : boolean
  + needsHelpDressing : boolean
  + needsHelpPersonalCare : boolean
  + recommendedStayType : StayType
}

class Stay {
  + status : string
  + startDate : date
  + endDate : date
  + discountApplied : boolean
}

class Proposal {
  + date : date
  + status : string
}

class Invoice {
  + amount : float
  + outstandingAmount : float
  + isPaid : boolean
}

class CreditNote {
  + amount : float
}

class PaymentEvent {
  + amount : float
  + date : date
}

Home "1" *-- "1..*" Department
Department "1" *-- "1..*" Room
Room "1" *-- "1..*" Bed
Bed "1" -- "1" Category
Category "1" -- "1" StayType

Inhabitant "1" -- "1..*" Stay
Stay "1" -- "1" Bed
Stay "1" -- "1" StayType

Inhabitant "1" -- "1" Registration
Registration "1" -- "1" Assessment

Stay "1" -- "0..*" Invoice
Invoice "1" -- "0..*" PaymentEvent

Stay "1" -- "0..*" Proposal
Proposal "1" -- "1" Inhabitant

Invoice "1" -- "0..1" CreditNote

@enduml

